code.en:
.toolbar {
  display: flex;
  align-items: center;
  gap: 0.75rem; /* not :last-child margin — Vue v-if leaves a trailing gap */
}
.toolbar__nav {
  flex: 1 1 auto; /* grow, shrink, content-sized basis */
  min-width: 0; /* allow shrink below content min (long SKU / filename) */
  overflow: auto;
}
.toolbar__actions {
  margin-inline-start: auto; /* park right; survives a third v-if child */
  flex: 0 0 auto;
}
/* flex: 1 alone does not stop a nowrap word overflowing. min-width: 0 does. */

code.vi:
.toolbar {
  display: flex;
  align-items: center;
  gap: 0.75rem; /* không margin :last-child — v-if Vue để lại gap cuối */
}
.toolbar__nav {
  flex: 1 1 auto; /* grow, shrink, basis theo nội dung */
  min-width: 0; /* cho co dưới min nội dung (SKU / tên file dài) */
  overflow: auto;
}
.toolbar__actions {
  margin-inline-start: auto; /* đậu phải; sống sót child v-if thứ ba */
  flex: 0 0 auto;
}
/* một mình flex: 1 không chặn từ nowrap tràn. min-width: 0 mới chặn. */

code.en:
.app {
  display: grid;
  grid-template-columns: minmax(0, 16rem) minmax(0, 1fr) minmax(0, 20rem);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas:
    'nav top top'
    'nav main inspector';
  min-height: 100dvh;
}
@media (max-width: 64rem) {
  .app {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas: 'top' 'main'; /* inspector dropped — no empty track */
  }
}
.gallery { grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr)); }

