code.en:
/* Dashboard cell: Grid owns the page, Flex owns the panel. */
.main {
  grid-area: main;
  min-height: 0; /* Grid track must shrink */
  display: flex;
  flex-direction: column;
}
.main__scroll {
  flex: 1 1 auto;
  min-height: 0; /* flex child must shrink or the page scrolls */
  overflow: auto;
}
/* Promote a form row to Grid when label/field/help must share tracks */
.form { display: grid; grid-template-columns: 8rem minmax(0, 1fr) 12rem; gap: 0.5rem 1rem; }

code.vi:
/* Ô dashboard: Grid sở hữu trang, Flex sở hữu panel. */
.main {
  grid-area: main;
  min-height: 0; /* track Grid phải co */
  display: flex;
  flex-direction: column;
}
.main__scroll {
  flex: 1 1 auto;
  min-height: 0; /* flex child phải co không thì trang cuộn */
  overflow: auto;
}
/* Nâng hàng form lên Grid khi label/field/help phải share track */
.form { display: grid; grid-template-columns: 8rem minmax(0, 1fr) 12rem; gap: 0.5rem 1rem; }

