code.en:
/* Sticky header: position + z-index => stacking context */
.header { position: sticky; top: 0; z-index: 20; }
/* Card hover transform => NEW context. A dropdown inside cannot beat .header */
.card:hover { transform: translateY(-2px); }
.card__menu { position: absolute; z-index: 9999; } /* trapped */
/* Fix: overlay root on body, one known scale — not 9999 inside the card */
.overlay-root { isolation: isolate; z-index: 40; }
/* Vue: <Teleport to="body"><div class="overlay-root">… */

code.vi:
