code.en:
.cell {
  min-width: 0; /* below min-content — without this, truncate never runs */
}
.cell__name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sku { overflow-wrap: anywhere; } /* show the whole unbreakable string */
.panel {
  min-height: 0;
  overflow: auto; /* inner scroll, not the page */
}
/* do not: overflow-x: hidden on body to hide a 1px scroll — WCAG reflow */

