code.en:
@layer reset, tokens, base, components, utilities;
@layer components {
  .form { display: grid; grid-template-columns: 8rem minmax(0, 1fr); }
  .form > .row { display: grid; grid-template-columns: subgrid; grid-column: 1 / -1; }
  .field:has(:invalid) { outline: 2px solid var(--danger); }
  .card:has(dialog[open]) { z-index: 2; } /* stacking — still name the context */
}
@layer utilities { .mt-0 { margin-top: 0; } } /* beats components at equal spec */
@supports not (grid-template-columns: subgrid) {
  .form > .row { grid-template-columns: 8rem minmax(0, 1fr); } /* duplicated tracks */
}

